style.css:
/* Aplica estilos al buscador principal de Google */
body {
  margin: 0;
  padding: 0;
  height: 100vh; /* Altura completa de la ventana */
  width: 100vw; /* Ancho completo de la ventana */
  background-image: url('https://indierocks.sfo3.cdn.digitaloceanspaces.com/wp-content/uploads/bfi_thumb/billie_eilish_22-681854at14kmzooi3n0y7jwn5tsrwtpdybg78avlbin1kmsug49eztbdg5152g.jpg');
  background-size: cover; /* Escala la imagen para cubrir la pantalla */
  background-position: center; /* Centra la imagen en la pantalla */
  background-repeat: no-repeat; /* Evita la repetición del fondo */
  overflow: hidden; /* Oculta cualquier desplazamiento */
}

/* Oculta el contenido no deseado para dejar solo el fondo */
